let body = $input.first().json.body || $input.first().json;
if (body && typeof body === 'object') {
  const bodyKeys = Object.keys(body);
  const jsonKey = bodyKeys.find(k => k.startsWith('{'));
  if (jsonKey) {
    const raw = Object.entries(body).map(([k, v]) => k + '=' + v).join('&');
    try { body = JSON.parse(raw); } catch (e) {
      const extract = (field) => { const re = new RegExp('"' + field + '":"([^"]*)"'); const m = raw.match(re); return m ? m[1] : ''; };
      body = { account_id: extract('account_id'), user_provider_id: extract('user_provider_id'), user_full_name: extract('user_full_name'), user_public_identifier: extract('user_public_identifier'), user_profile_url: extract('user_profile_url') };
    }
  }
}
const data = body.data || body.object || body;
let accountId = body.account_id || data.account_id || '';
const providerId = String(data.user_provider_id || data.provider_id || data.id || '');
let name = data.user_full_name || data.name || data.display_name || '';
const publicId = data.user_public_identifier || data.public_identifier || '';
let profileUrl = data.user_profile_url || data.public_profile_url || data.profile_url || '';
if (!profileUrl && publicId) profileUrl = 'https://www.linkedin.com/in/' + publicId;
if (!profileUrl && providerId) profileUrl = 'https://www.linkedin.com/in/' + providerId;
let prenom = '';
if (name) prenom = name.split(/\s+/)[0] || '';
if (prenom) prenom = prenom.charAt(0).toUpperCase() + prenom.slice(1).toLowerCase();
if (!accountId) accountId = 'Vnu6KlyEQPW_BiX76jRMcw';
if (!providerId) throw new Error('Donnees webhook incompletes: providerId manquant');
return [{ json: { accountId, providerId, name, prenom, publicId, profileUrl } }];

const resp = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.github.com/repos/Martenous2000/mon-setter-bot/contents/prompts/personas/franck-andrianarivony.md',
  headers: { 'Authorization': 'token YOUR_GITHUB_TOKEN', 'Accept': 'application/vnd.github.v3.raw', 'User-Agent': 'n8n-francka-workflow' },
});
const personaMd = typeof resp === 'string' ? resp : (resp.toString ? resp.toString() : JSON.stringify(resp));
return [{ json: { ...$input.first().json, personaMd } }];

const contactData = $('Extract Contact Info').first().json;
const profile = $('Scrape Profile (Unipile)').first().json || {};
const personaMd = $input.first().json.personaMd || '';
const prenom = contactData.prenom || '';
const providerId = contactData.providerId;
const profileUrl = contactData.profileUrl || '';
const headline = profile.headline || '';
const name = contactData.name || '';

function relativeAgeToDays(v) {
  if (!v) return 9999;
  const m = String(v).match(/^(\\d+)\\s*(h|d|w|mo|y)/i);
  if (!m) return 9999;
  const n = parseInt(m[1], 10);
  const unit = m[2].toLowerCase();
  if (unit === 'h') return n / 24;
  if (unit === 'd') return n;
  if (unit === 'w') return n * 7;
  if (unit === 'mo') return n * 30;
  if (unit === 'y') return n * 365;
  return 9999;
}

let posts = [];
try {
  const raw = $('Scrape Posts (Unipile)').first().json;
  posts = raw.items || raw.posts || (Array.isArray(raw) ? raw : []);
  if (!Array.isArray(posts)) posts = [];
} catch(e) { posts = []; }

const recentPosts = posts.filter(p => {
  const ageDays = relativeAgeToDays(p.date);
  const text = (p.text || p.content || '').trim();
  return ageDays <= 14 && text.length > 20;
}).sort((a,b) => relativeAgeToDays(a.date) - relativeAgeToDays(b.date)).slice(0, 1);

const hasPosts = recentPosts.length > 0;
let userContent;
if (hasPosts) {
  const postText = (recentPosts[0].text || recentPosts[0].content || '').substring(0, 600);
  userContent = 'Lead first name: ' + prenom + '\nThis is right after they accepted our connection request.\nRecent LinkedIn post to react to:\n' + postText;
} else {
  userContent = 'Lead first name: ' + prenom + '\nThis is right after they accepted our connection request.\nNo recent post available. Headline/bio: ' + (headline || '(empty)');
}

const systemPrompt = 'Below is the full persona and messaging instructions for this LinkedIn account (Franck Andrianarivony). Follow the Icebreaker section EXACTLY as written in the persona (format, tone, language, tutoiement/vouvoiement, greeting word, forbidden words/punctuation) - the persona itself defines the language and register, do not assume a default. This message follows an ACCEPTED connection request (not an incoming one), so briefly acknowledge the connection before the Type 1 reaction if natural, but keep the same constraints from the persona. If a recent post is provided, react to it (Type 1) exactly as specified. If no post is provided, write a short opener in the same tone/register/language reformulating their activity from the headline/bio, ending with a short open question.\n\n' + personaMd + '\n\nReply ONLY with the final icebreaker message, nothing else.';

let icebreaker = '';
try {
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: { 'Authorization': 'Bearer YOUR_OPENROUTER_API_KEY', 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'anthropic/claude-opus-4', messages: [ { role: 'system', content: systemPrompt }, { role: 'user', content: userContent } ], temperature: 0.5, max_tokens: 150 }),
    json: true,
  });
  icebreaker = (resp.choices[0].message.content || '').trim();
  if ((icebreaker.startsWith('"') && icebreaker.endsWith('"'))) icebreaker = icebreaker.slice(1, -1);
} catch(e) {
  icebreaker = 'Bonjour ' + prenom + ', je viens de voir votre profil, ca m\'interesse ce que vous faites. Vous vous concentrez sur quoi en ce moment';
}

return [{ json: { accountId: contactData.accountId, providerId, prenom, headline, profileUrl, icebreaker, hasPosts, name } }];

